questionvariables.text:
/* Design backwards: pick the solution x0 and common angle A, then build two
   distinct linear expressions that both equal A at x = x0. */
A  : rand([45,50,55,60]);
x0 : rand([8,9,10,11,12,13,14,15]);
a1 : rand([3,4]);
a2 : rand(delete(a1,[2,3]));
b1 : A - a1*x0;
b2 : A - a2*x0;
e1 : a1*x + b1;
e2 : a2*x + b2;
taX : x0;
taA : A;
